-- Price change approval (slug: price-change), audience INTERNAL.
--
-- Marketing requests a package price change at one site. Dan Petrelle
-- (dpetrelle@splashcarwashes.com) approves with a signature or denies with a
-- note, from a no-sign-in emailed link or from /admin/approvals. The requester
-- is emailed the result either way, with the completed-form PDF attached.
--
-- RECORDS THE DECISION ONLY. Nothing here writes to pricing_simple; prices
-- change when somebody applies them deliberately.
--
-- PREREQUISITE: supabase/form-approval-links-01.sql. Without that table the
-- emailed button falls back to the signed-in submission page.
--
-- Generated by scripts/gen-price-change.ts, the source of truth:
--   cd packages/forms-schema && npx tsx ../../scripts/gen-price-change.ts out.json
--
-- NOT YET APPLIED.
-- SAFE TO RE-RUN: upserts the form by slug and overwrites the draft schema.
-- The form is created as a DRAFT. Publishing it in the builder mints
-- /forms/price-change and designates site_number as its location scope.

insert into public.forms
  (slug, title, description, audience, status, notify_webhook,
   turnstile_required, success_message, created_by, last_edited_by)
values
  ('price-change',
   'Price change approval',
   'Request a package price change at a site. Tick each package that is changing and enter its current and new prices.',
   'internal',
   'draft',
   true,
   false,
   'Thanks - your request is with Dan for approval. You will get an email when he approves or denies it.',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89',
   'f42882fd-ee5a-433e-b10b-713d5dff8a89')
on conflict (slug) do update
  set title = excluded.title,
      description = excluded.description,
      audience = excluded.audience,
      turnstile_required = excluded.turnstile_required,
      success_message = excluded.success_message,
      last_edited_at = now();

with f as (select id, draft_version_id from public.forms where slug = 'price-change'),
ins as (
  insert into public.form_versions (form_id, version_number, is_draft, schema)
  select f.id, 1, true, '{"fields":[{"key":"site_number","id":"edf0729e","type":"short_text","label":"Site number","required":true,"maxLength":3,"helpText":"The 3-digit site number, e.g. 019.","show_in_queue":true},{"key":"site_name","id":"960125cf","type":"lookup","label":"Site","required":true,"keyFieldId":"edf0729e","keyColumn":"pricing_simple.site","sourceTable":"pricing_simple","sourceColumn":"location_pretty","resolutionMode":"prefill_visible","nullBehavior":"block_submit","show_in_queue":true},{"key":"packages","id":"41a6ed19","type":"package_price_grid","label":"Packages affected","required":true,"keyFieldKey":"site_number","keyColumn":"pricing_simple.site","helpText":"Enter the current single and monthly price as they are today. Leave a new price blank if it isn''t changing."},{"key":"notes","id":"3c026dd7","type":"long_text","label":"Notes for the approver","required":false,"maxLength":2000,"helpText":"Optional: reason for the change, timing, anything Dan should know."}],"workflow":{"default_stage":"notify_dan","stages":[{"id":"notify_dan","label":"Email Dan","kind":"email","recipients":[{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]}],"subject_template":"Price change approval needed: {field.site_name} ({field.site_number})","body_template":"{submitter.email} has requested a price change at {field.site_name} (site {field.site_number}).\n\n{payload.summary}\n\n{approval.link}\n\nThe link works without signing in and expires in 7 days. Approving needs your signature; denying needs a short note.","transitions":[{"to":"dan_review","label":"Sent"}]},{"id":"dan_review","label":"Dan''s approval","kind":"approval","approver_source":{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]},"transitions":[{"to":"approved_email","label":"Approve","requires":{"signature":true}},{"to":"denied_email","label":"Deny","requires":{"note":true}}]},{"id":"approved_email","label":"Email approval","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Approved: price change at {field.site_name} ({field.site_number})","body_template":"Your price change request for {field.site_name} (site {field.site_number}) was {outcome.label} by {decision.by}.\n\n{payload.summary}\n\nThe signed approval is attached. Prices have not been changed yet; this records the approval only.\n\n{submission.url}","transitions":[{"to":"approved","label":"Sent"}]},{"id":"denied_email","label":"Email denial","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Denied: price change at {field.site_name} ({field.site_number})","body_template":"Your price change request for {field.site_name} (site {field.site_number}) was {outcome.label} by {decision.by}.\n\nReason: {decision.note}\n\n{payload.summary}\n\n{submission.url}","transitions":[{"to":"denied","label":"Sent"}]},{"id":"approved","label":"Approved","kind":"outcome","tint":"success","transitions":[]},{"id":"denied","label":"Denied","kind":"outcome","tint":"danger","transitions":[]}]}}'::jsonb
    from f where f.draft_version_id is null
  returning id, form_id
)
update public.forms set draft_version_id = ins.id, last_edited_at = now()
  from ins where public.forms.id = ins.form_id;

update public.form_versions v
   set schema = '{"fields":[{"key":"site_number","id":"edf0729e","type":"short_text","label":"Site number","required":true,"maxLength":3,"helpText":"The 3-digit site number, e.g. 019.","show_in_queue":true},{"key":"site_name","id":"960125cf","type":"lookup","label":"Site","required":true,"keyFieldId":"edf0729e","keyColumn":"pricing_simple.site","sourceTable":"pricing_simple","sourceColumn":"location_pretty","resolutionMode":"prefill_visible","nullBehavior":"block_submit","show_in_queue":true},{"key":"packages","id":"41a6ed19","type":"package_price_grid","label":"Packages affected","required":true,"keyFieldKey":"site_number","keyColumn":"pricing_simple.site","helpText":"Enter the current single and monthly price as they are today. Leave a new price blank if it isn''t changing."},{"key":"notes","id":"3c026dd7","type":"long_text","label":"Notes for the approver","required":false,"maxLength":2000,"helpText":"Optional: reason for the change, timing, anything Dan should know."}],"workflow":{"default_stage":"notify_dan","stages":[{"id":"notify_dan","label":"Email Dan","kind":"email","recipients":[{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]}],"subject_template":"Price change approval needed: {field.site_name} ({field.site_number})","body_template":"{submitter.email} has requested a price change at {field.site_name} (site {field.site_number}).\n\n{payload.summary}\n\n{approval.link}\n\nThe link works without signing in and expires in 7 days. Approving needs your signature; denying needs a short note.","transitions":[{"to":"dan_review","label":"Sent"}]},{"id":"dan_review","label":"Dan''s approval","kind":"approval","approver_source":{"type":"static_emails","emails":["dpetrelle@splashcarwashes.com"]},"transitions":[{"to":"approved_email","label":"Approve","requires":{"signature":true}},{"to":"denied_email","label":"Deny","requires":{"note":true}}]},{"id":"approved_email","label":"Email approval","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Approved: price change at {field.site_name} ({field.site_number})","body_template":"Your price change request for {field.site_name} (site {field.site_number}) was {outcome.label} by {decision.by}.\n\n{payload.summary}\n\nThe signed approval is attached. Prices have not been changed yet; this records the approval only.\n\n{submission.url}","transitions":[{"to":"approved","label":"Sent"}]},{"id":"denied_email","label":"Email denial","kind":"email","recipients":[{"type":"payload_field","field_key":"submitter.email"}],"attach_pdf":true,"subject_template":"Denied: price change at {field.site_name} ({field.site_number})","body_template":"Your price change request for {field.site_name} (site {field.site_number}) was {outcome.label} by {decision.by}.\n\nReason: {decision.note}\n\n{payload.summary}\n\n{submission.url}","transitions":[{"to":"denied","label":"Sent"}]},{"id":"approved","label":"Approved","kind":"outcome","tint":"success","transitions":[]},{"id":"denied","label":"Denied","kind":"outcome","tint":"danger","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'price-change' and v.id = f.draft_version_id;

select f.slug, f.audience, f.status,
       jsonb_array_length(v.schema->'fields') as fields,
       jsonb_array_length(v.schema->'workflow'->'stages') as stages,
       v.schema->'workflow'->>'default_stage' as starts_at
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'price-change';
